// noprotect  (turns off the p5 editor's loop protection, which breaks on this sketch's physics loops)
// O'Keeffe's Subjects — p5.js
// A drill-down bubble chart of the catalogue raisonné by subject.
// Click a bubble to break it into its parts; the last level shows one dot per work.
// Expects a global DATA = { tree: [name, count, children[], workIndexes[]], works: [...] }
//   works: [objectId, title, date, institution, primaryImageDamId, mediumAndDimensions, year, subjectFromClaude]
//
// Levels 1–2 regroup the museum's Subject Categories. Deeper levels were derived by Claude
// from titles, related-work groups and brief descriptions.
//
// Controls: click a bubble to open it · click the path at the top (or press Esc / Backspace) to go back
// hover a bubble for its name and count · in a set of works, click a dot to see the work

const ACCESS_URL = id => `https://access-ok.okeeffemuseum.org/object/${id}/`;
const IIIF = (dam, w, h) => `https://iiif.okeeffemuseum.org/image/iiif/2/${dam}/full/!${w},${h}/0/default.jpg`;
const TOP_ORDER = ["Landscapes", "Nature", "Abstractions", "Architecture and built environment", "Portraits and human figures", "Human-made objects", "Sketchbooks and other"];

const PALETTES = {
  light: { ground: "#EEF0EE", paper: "#F8F9F7", ink: "#1D2226", ink2: "#4C555C", ink3: "#7C868D", rule: "#D5DAD8", accent: "#A3302A",
           cat: ["#B5533A", "#5F8446", "#3E5E9C", "#B0822F", "#7D4A7A", "#2C7C83", "#7C868D"],
           dec: ["#C9971F", "#D3822B", "#C9662F", "#B84B36", "#9E3948", "#80345C", "#61336C", "#453577", "#2E3B7C"] },
  dark:  { ground: "#15191B", paper: "#1C2124", ink: "#E6E9E8", ink2: "#B3BBBF", ink3: "#848E94", rule: "#33393D", accent: "#E8746A",
           cat: ["#DB7A5E", "#8DB26F", "#7C9AD6", "#D9AE5C", "#B07AAE", "#5DB0B6", "#9AA3A9"],
           dec: ["#E6BE5C", "#EBA35A", "#E88A5E", "#DD7166", "#CC6478", "#B45F8E", "#9C63A6", "#8671BC", "#7688CC"] }
};

let P, TREE, WORKS, path = [], bubbles = [], ghosts = [], hover = null, pinned = null, card, hits = [];
let H = 640, reduceMotion = false;

function pickPalette() {
  const attr = document.documentElement.getAttribute("data-theme");
  const dark = attr ? attr === "dark" : window.matchMedia("(prefers-color-scheme: dark)").matches;
  P = dark ? PALETTES.dark : PALETTES.light;
  if (card) renderCard();
}
function stageWidth() {
  const host = document.getElementById("stage");
  return Math.max(320, host ? host.clientWidth : windowWidth - 32);
}

function setup() {
  TREE = DATA.tree; WORKS = DATA.works;
  pickPalette();
  H = windowWidth < 700 ? 520 : 640;
  const c = createCanvas(stageWidth(), H);
  const stage = document.getElementById("stage");
  if (stage) c.parent("stage");
  c.elt.setAttribute("role", "img");
  c.elt.setAttribute("aria-label", "Bubble chart of Georgia O'Keeffe's catalogue raisonné by subject; click a bubble to break it into smaller subjects");
  pixelDensity(Math.min(2, window.devicePixelRatio || 1));
  reduceMotion = window.matchMedia("(prefers-reduced-motion: reduce)").matches;
  window.matchMedia("(prefers-color-scheme: dark)").addEventListener("change", pickPalette);
  new MutationObserver(pickPalette).observe(document.documentElement, { attributes: true, attributeFilter: ["data-theme"] });
  card = createDiv("");
  if (stage) card.parent(stage.parentNode);
  card.style("max-width", "980px"); card.style("padding", "8px 0 8px");
  card.style("font-family", "'Public Sans', system-ui, sans-serif"); card.style("font-size", "15px"); card.style("line-height", "1.5");
  enter([], width / 2, height / 2);
}
function windowResized() { resizeCanvas(stageWidth(), H); layoutTargets(); }

// ---------- tree helpers ----------
function nodeAt(p) { let n = TREE; for (const i of p) { n = n[2][i]; } return n; }
function catIndex(p) { return p.length ? TOP_ORDER.indexOf(TREE[2][p[0]][0]) : -1; }
function isWorks(node) { return node[2].length === 0; }
function works(node) { return node[3].length ? node[3] : node[2].flatMap(works); }

// ---------- entering a level ----------
function enter(newPath, ox, oy, fromBubble) {
  // old bubbles fade out; the one we clicked swells into the new view
  ghosts = bubbles.map(b => Object.assign({}, b, { born: millis(), swell: b === fromBubble }));
  path = newPath; pinned = null; hover = null;
  const node = nodeAt(path);
  const base = catIndex(path);
  if (isWorks(node)) {
    bubbles = node[3].map((wi, k) => ({ kind: "work", wi, n: 1, label: WORKS[wi][1], ci: base, shade: 0,
      x: ox + random(-20, 20), y: oy + random(-20, 20), r: 1, vx: 0, vy: 0, idx: k }));
  } else {
    bubbles = node[2].map((kid, k) => ({ kind: "node", k, n: kid[1], label: kid[0], ci: path.length ? base : k,
      shade: path.length ? k : 0, x: ox + random(-30, 30), y: oy + random(-30, 30), r: 1, vx: 0, vy: 0 }));
  }
  layoutTargets();
  if (reduceMotion) bubbles.forEach(b => { b.r = b.tr; settle(200); });
  renderCard();
}
function layoutTargets() {
  const total = bubbles.reduce((s, b) => s + b.n, 0) || 1;
  const area = (width - 40) * (height - 110) * (bubbles.length > 40 ? 0.5 : 0.56);
  const k = sqrt(area / (PI * total));
  const cap = min(width, height - 110) * (bubbles.length === 1 ? 0.36 : 0.3);
  bubbles.forEach(b => { b.tr = min(cap, max(bubbles[0] && bubbles[0].kind === "work" ? 3 : 10, sqrt(b.n) * k)); });
  if (bubbles.length && bubbles[0].kind === "work") { const r = min(26, bubbles[0].tr); bubbles.forEach(b => b.tr = r); }
}

// ---------- physics: pull toward the center, push apart where bubbles overlap ----------
function settle(iter) {
  const cx = width / 2, cy = 60 + (height - 60) / 2;
  for (let it = 0; it < iter; it++) {
    for (const b of bubbles) { b.vx += (cx - b.x) * 0.0025; b.vy += (cy - b.y) * 0.0035; }
    for (let i = 0; i < bubbles.length; i++) { for (let j = i + 1; j < bubbles.length; j++) {
      const a = bubbles[i], b = bubbles[j];
      let dx = b.x - a.x, dy = b.y - a.y, d = sqrt(dx * dx + dy * dy) || 0.01;
      const m = a.r + b.r + (a.kind === "work" ? 1.5 : 4);
      if (d < m) { const push = (m - d) / d * 0.5; dx *= push; dy *= push; a.x -= dx; a.y -= dy; b.x += dx; b.y += dy; }
    } }
    for (const b of bubbles) {
      b.vx *= 0.82; b.vy *= 0.82; b.x += b.vx; b.y += b.vy;
      b.x = constrain(b.x, b.r + 4, width - b.r - 4); b.y = constrain(b.y, 62 + b.r, height - b.r - 6);
    }
  }
}

// ---------- draw ----------
function shadeOf(b) {
  if (b.kind === "work") {        // one dot per work, colored by the decade it was made
    const y = WORKS[b.wi][6];
    return color(y ? P.dec[constrain(floor((y - 1900) / 10), 0, 8)] : P.ink3);
  }
  const c = color(P.cat[max(0, b.ci)]);
  if (!path.length) return c;
  // siblings step lighter and darker around the parent's color
  const steps = [0, 0.18, -0.14, 0.32, -0.26, 0.44, 0.08, -0.06, 0.26, -0.2];
  const s = steps[b.shade % steps.length];
  return s >= 0 ? lerpColor(c, color(P.paper), s) : lerpColor(c, color(P.ink), -s);
}
function draw() {
  background(P.ground);
  hits = [];
  for (const b of bubbles) { b.r += (b.tr - b.r) * (reduceMotion ? 1 : 0.14); }
  settle(3);

  // ghosts of the previous level
  const now = millis();
  ghosts = ghosts.filter(g => now - g.born < 420);
  for (const g of ghosts) {
    const t = (now - g.born) / 420;
    const c = shadeOf(g); c.setAlpha(255 * (1 - t) * (g.swell ? 0.55 : 0.9));
    noStroke(); fill(c);
    circle(g.x, g.y, 2 * (g.swell ? g.r * (1 + t * 2.2) : g.r * (1 - t)));
  }

  let over = null;
  for (const b of bubbles) { if (dist(mouseX, mouseY, b.x, b.y) < b.r) over = b; }
  if (over !== hover) { hover = over; if (hover && hover.kind === "work" && !pinned) renderCard(); if (!hover && !pinned) renderCard(); }

  for (const b of bubbles) {
    const c = shadeOf(b);
    const focus = b === hover || b === pinned;
    noStroke(); fill(c); circle(b.x, b.y, b.r * 2);
    if (focus) { noFill(); stroke(P.ink); strokeWeight(2); circle(b.x, b.y, b.r * 2 + 6); noStroke(); }
    if (b.kind === "node" && b.r > 26) drawLabel(b, c);
  }
  if (hover) drawTip(hover);
  drawCrumbs();
  cursor(hover || hits.some(h => inHit(h)) ? HAND : ARROW);
}
function inkOn(c) { return (red(c) * 0.299 + green(c) * 0.587 + blue(c) * 0.114) > 150 ? "#1D2226" : "#FFFFFF"; }
function drawLabel(b, c) {
  const ink = inkOn(c);
  const size = constrain(b.r / 5.2, 11, 20);
  textFont("Public Sans"); textStyle(BOLD); textSize(size); textAlign(CENTER, CENTER); fill(ink); noStroke();
  const w = b.r * 1.55;
  textWrap(WORD);
  const lines = wrapLines(b.label, w);
  const lh = size * 1.15, total = lines.length * lh + size * 1.1;
  let y = b.y - total / 2 + lh / 2;
  if (lines.length * lh > b.r * 1.5) { lines.length = 1; lines[0] = clipText(b.label, 16); }
  lines.forEach(l => { text(l, b.x, y); y += lh; });
  textStyle(NORMAL); textFont("IBM Plex Mono"); textSize(max(10, size * 0.72));
  const cc = color(ink); cc.setAlpha(210); fill(cc);
  text(b.n.toLocaleString(), b.x, y + 1);
}
function wrapLines(s, w) {
  const words = s.split(" "), out = []; let line = "";
  for (const wd of words) { const t = line ? line + " " + wd : wd; if (textWidth(t) > w && line) { out.push(line); line = wd; } else line = t; }
  if (line) out.push(line);
  return out;
}
function drawTip(b) {
  let label, sub;
  if (b.kind === "work") { const w = WORKS[b.wi]; label = `${w[1]}, ${w[2]}`; sub = w[3] || ""; }
  else { const kid = nodeAt(path)[2][b.k]; label = b.label; sub = `${b.n.toLocaleString()} works · ${isWorks(kid) ? "click to see each work" : "click to open"}`; }
  textFont("Public Sans"); textSize(13);
  const tw = max(textWidth(clipText(label, 64)), textWidth(sub)) + 20;
  let x = constrain(mouseX + 14, 4, width - tw - 4), y = constrain(mouseY + 16, 60, height - 50);
  fill(P.paper); stroke(P.rule); strokeWeight(1); rect(x, y, tw, 44, 5); noStroke();
  fill(P.ink); textAlign(LEFT, TOP); text(clipText(label, 64), x + 10, y + 7);
  fill(P.ink3); textSize(12); text(sub, x + 10, y + 25);
}
function drawCrumbs() {
  textFont("Public Sans"); textSize(14); textAlign(LEFT, CENTER); noStroke();
  let x = 0; const y = 24;
  const names = ["All subjects"].concat(path.map((_, i) => nodeAt(path.slice(0, i + 1))[0]));
  names.forEach((nm, i) => {
    const last = i === names.length - 1;
    textStyle(last ? BOLD : NORMAL);
    const w = textWidth(nm);
    fill(last ? P.ink : P.ink2); text(nm, x, y);
    if (!last) {
      stroke(P.ink3); strokeWeight(1); line(x, y + 10, x + w, y + 10); noStroke();
      hits.push({ x, y: y - 12, w, h: 26, fn: () => goTo(i) });
      fill(P.ink3); textStyle(NORMAL); text("  ›  ", x + w, y); x += textWidth("  ›  ");
    }
    x += w;
  });
  textStyle(NORMAL);
  const node = nodeAt(path);
  textFont("IBM Plex Mono"); textSize(12); fill(P.ink3); textAlign(RIGHT, CENTER);
  const note = isWorks(node) ? `${node[1]} works · one dot per work` : path.length >= 2 ? "levels below this were grouped by Claude from titles" : `${node[1].toLocaleString()} works`;
  text(note, width, y);
  if (path.length) {
    textAlign(LEFT, CENTER); textFont("Public Sans"); textSize(12.5); fill(P.ink3);
    text("← back (Esc)", 0, 48);
    hits.push({ x: 0, y: 38, w: 90, h: 20, fn: () => goTo(path.length - 1) });
  }
}
function goTo(depth) {
  const cx = width / 2, cy = height / 2;
  enter(path.slice(0, depth), cx, cy, null);
}

// ---------- card below the canvas ----------
function esc(s) { return String(s).replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;"); }
function workCard(wi, big) {
  const [id, title, date, inst, img, md, , fromClaude] = WORKS[wi];
  const thumb = img ? `<img src="${IIIF(img, big ? 240 : 160, big ? 200 : 140)}" alt="${esc(title)}" loading="lazy" onerror="this.remove()" style="flex:none;display:block;max-height:${big ? 100 : 70}px;max-width:${big ? 160 : 110}px;border-radius:2px">` : "";
  return `<a href="${ACCESS_URL(id)}" target="_blank" rel="noopener" style="display:flex;gap:12px;align-items:center;padding:10px 12px;border:1px solid ${P.rule};border-radius:4px;text-decoration:none;color:inherit;background:${P.paper}">
    ${thumb}<span style="min-width:0">
      <span style="display:block;font-family:'Newsreader',Georgia,serif;font-style:italic;font-size:${big ? 20 : 16}px;line-height:1.25;color:${P.ink}">${esc(title)}</span>
      ${big && md ? `<span style="display:block;font-size:13px;color:${P.ink2}">${esc(md)}</span>` : ""}
      <span style="display:block;font-size:12.5px;color:${P.ink2}">${esc(date)}${inst ? " · " + esc(inst) : ""}</span>
      ${fromClaude ? `<span style="display:inline-block;margin-top:3px;font-size:10.5px;color:${P.ink3};border:1px solid ${P.ink3};border-radius:999px;padding:0 6px">subject assigned by Claude</span>` : ""}
      ${big ? `<span style="display:block;font-size:13px;font-weight:500;color:${P.accent};margin-top:5px">View on Access O'Keeffe ↗</span>` : ""}
    </span></a>`;
}
function renderCard() {
  if (!card) return;
  const node = nodeAt(path);
  const focus = pinned || (hover && hover.kind === "work" ? hover : null);
  if (isWorks(node)) {
    const list = node[3];
    const head = focus ? `<div style="max-width:640px;margin-bottom:14px">${workCard(focus.wi, true)}</div>` : "";
    const legend = P.dec.map((c, i) => `<span style="display:inline-flex;align-items:center;gap:5px"><span style="width:10px;height:10px;border-radius:50%;background:${c}"></span>${1900 + i * 10}s</span>`).join("");
    card.html(`${head}<div style="display:flex;flex-wrap:wrap;gap:4px 12px;font-family:'IBM Plex Mono',monospace;font-size:11.5px;color:${P.ink3};margin-bottom:10px">Dots are colored by decade: ${legend}</div>
      <div style="font-size:13px;color:${P.ink3};margin-bottom:8px">All ${list.length} works in <b style="color:${P.ink}">${esc(node[0])}</b>, earliest first</div>
      <div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(250px,1fr));gap:8px">${list.map(wi => workCard(wi, false)).join("")}</div>`);
    return;
  }
  const kids = node[2];
  const derived = path.length >= 2;
  const origin = !path.length
    ? `The seven big bubbles categorize O'Keeffe's Subjects (for example, Plants, Trees, Bones, Shells and Rocks all sit inside <b style="color:${P.ink}">Nature</b>). Click a bubble to break it apart.`
    : derived
      ? `These groups were worked out by Claude from titles, related-work groups and brief descriptions. They are a starting point for curatorial review, not museum records.`
      : `These are the museum's Subject Categories inside ${esc(node[0])}. From the next level down, groups were worked out by Claude from titles.`;
  card.html(`<div style="color:${P.ink2};max-width:72ch">${origin}</div>
    <div style="display:flex;flex-wrap:wrap;gap:6px 18px;margin-top:10px;font-size:13px;color:${P.ink2}">
      ${kids.map(k => `<span><b style="font-weight:600;color:${P.ink}">${esc(k[0])}</b> ${k[1].toLocaleString()}</span>`).join("")}
    </div>`);
}

// ---------- interaction ----------
function inHit(h) { return mouseX >= h.x && mouseX <= h.x + h.w && mouseY >= h.y && mouseY <= h.y + h.h; }
function mousePressed() {
  if (mouseX < 0 || mouseX > width || mouseY < 0 || mouseY > height) return;
  for (const h of hits) { if (inHit(h)) { h.fn(); return false; } }
  if (!hover) { if (pinned) { pinned = null; renderCard(); } return; }
  if (hover.kind === "work") { pinned = hover === pinned ? null : hover; renderCard(); return false; }
  enter(path.concat([hover.k]), hover.x, hover.y, hover);
  return false;
}
function keyPressed() {
  if ((keyCode === ESCAPE || keyCode === BACKSPACE) && path.length) { goTo(path.length - 1); return false; }
}

// ---------- helpers ----------
function clipText(s, n) { return s.length > n ? s.slice(0, n - 1).trim() + "…" : s; }